import {signedIn,authView,checkAuth,bindAuth,signOutButton,lostSession} from './auth.js';
import {patchDOM} from './dom.js';
import {explorerView,bindExplorer} from './explorer.js';
import {researchView} from './research.js';
import {ibkrPanel,ibkrMarket} from './ibkr.js';
import {money,pct,stamp,esc,selectRange,chartHTML,bindChart} from './charts.js';
const main=document.querySelector('#main');
const categories=['Crypto','Stocks','ETFs','Options','Futures','IPOs'];
let ibkr=null,ibkrAsset=null,ibkrBusy=false,lastInteraction=0,lastIBKRPoll=0;
let account='Options research',engine='Options research';
let page='overview',category='Crypto',assetId='BTC/CAD',range='ALL',marketRange='1W',region='Canada',paper=null,market=null,errors={},busy=false,chartSeries=[];
const number=v=>Number.isFinite(v)?v.toLocaleString('en-CA',{maximumFractionDigits:8}):'—';
const signed=v=>Number.isFinite(v)?`${v>=0?'+':'−'}${money(Math.abs(v))}`:'—';
const tone=v=>v<0?'negative':'positive';
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const empty=(title,description)=>`<div class="empty"><span class="empty-icon">⌁</span><h3>${title}</h3><p>${description}</p></div>`;
const stat=(label,value,detail='',cls='')=>`<article class="stat"><span class="label">${label}</span><strong class="${cls}">${value}</strong><small>${detail}</small></article>`;
const tabs=(items,selected,attr)=>`<div class="segmented">${items.map(x=>`<button ${attr}="${x}" aria-pressed="${x===selected}" class="${x===selected?'selected':''}">${x}</button>`).join('')}</div>`;
function heartbeat(){if(!paper)return {name:'Ledger unavailable',type:'warning'};const age=Date.now()-(paper.heartbeat?.startedAt||0);return paper.halted?{name:'Risk stop active',type:'warning'}:age>paper.expectedIntervalMs*2?{name:'Worker overdue',type:'warning'}:paper.heartbeat?.status==='ok'?{name:'Worker healthy',type:'positive'}:{name:'Worker degraded',type:'warning'};}
function header(kicker,title,subtitle){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><button id="refresh" aria-label="Refresh data" class="button" ${busy?'disabled':''}>↻ <span>${busy?'Refreshing':'Refresh'}</span></button></div>`;}
function notice(){const h=heartbeat();return `<div class="notice"><span>${badge(h.name,h.type)} ${paper?`Last cycle ${stamp(paper.heartbeat?.startedAt)} · ${paper.runtime==='Local worker'?'Separate local ledger · crypto worker not started by IBKR pilot':'Hourly, best effort'}${paper.valuationStale?' · Holdings valuation is stale':''}`:'Current balance cannot be verified.'}</span><a href="https://github.com/git-jainamshah/northstar/actions/workflows/paper-pilot.yml" target="_blank" rel="noopener">Worker logs ↗</a></div>${errors.paper?`<p class="error" role="status">${esc(errors.paper)}</p>`:''}`;}
function table(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function ranges(selected,attr='data-range'){return tabs(['1D','1W','1M','ALL'],selected,attr);}
function portfolio(){const research=account==='Options research',o=ibkr?.research;const r=research?(o?{...o,createdAt:o.createdAt,maxDrawdown:o.maxDrawdown,valuationStale:o.valuationStale||Date.now()-o.asOf>(ibkr?.transport==='hosted'?90000:10000),unrealizedPnl:o.position?o.position.mark-o.position.cost:0,positions:o.position?[{id:o.position.symbol,qty:1,liquidation:o.position.mark,unrealizedPnl:o.position.mark-o.position.cost}]:[],history:o.history.map(p=>({...p,stale:p.equity===null}))}:null):paper;const history=selectRange(r?.history||[],range);chartSeries=[{name:'Portfolio',color:'#65ebc5',points:history.map(p=>({time:p.time,value:p.stale?null:p.equity}))}];return header('YOUR CAPITAL, IN FOCUS','Portfolio','Your simulated capital. Every move accounted for.')+ibkrPanel(ibkr)+tabs(['Options research','Crypto $100'],account,'data-account')+(research?'':notice())+`<section class="hero-grid"><article class="balance"><span class="label">TOTAL EQUITY <span>CAD</span></span><div class="balance-value">${money(r?.equity)}</div><div class="balance-change ${tone(r?.pnl)}">${signed(r?.pnl)} <span>${pct(r?r.pnl/r.initialCash:null)} all time</span></div><div class="balance-foot">${badge('SIMULATED')} Started with CAD ${research?'$10,000':'$100'}${r?.valuationStale?' · Stale estimate':''}</div></article><div class="stat-grid">${stat('Available cash',money(r?.cash),'CAD · ready to deploy')}${stat('Open positions',r?String(r.positions.length):'—','No leverage')}${stat('Realized P/L',signed(r?.realizedPnl),'Closed trades',tone(r?.realizedPnl))}${stat('Unrealized P/L',signed(r?.unrealizedPnl),'After estimated exit costs',tone(r?.unrealizedPnl))}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">PERFORMANCE</span><h2>Portfolio value</h2></div>${ranges(range)}</div>${chartHTML(chartSeries,{label:'Recorded portfolio equity in CAD, plotted by timestamp'})}<div class="panel-foot"><span><i class="legend-dot"></i> Portfolio · CAD</span><span>Recorded worker observations · gaps between cycles are not live ticks</span></div></section><div class="two-col"><section class="panel"><div class="panel-head"><h2>Holdings</h2>${badge(`${r?.positions.length??'—'} POSITIONS`)}</div>${r?r.positions.length?table(['Asset','Quantity','Value','P/L'],r.positions.map(p=>`<tr><td><b>${esc(p.id)}</b>${p.stale?'<small>Stale valuation</small>':''}</td><td>${number(p.qty)}</td><td>${money(p.liquidation)}</td><td class="${tone(p.unrealizedPnl)}">${signed(p.unrealizedPnl)}</td></tr>`)):empty('Cash is a position, too.','The strategy is waiting for an eligible setup. Your simulated capital is in CAD.'):empty('Ledger unavailable','Holdings appear once the saved account can be read.')}</section><section class="panel"><div class="panel-head"><h2>Account breakdown</h2><span class="dim">Since inception</span></div><div class="details">${detail('Starting capital',r?money(r.initialCash):'—')}${detail('Net profit / loss',signed(r?.pnl))}${detail('Simulated fees paid',money(r?.fees))}${detail('Maximum drawdown',Number.isFinite(r?.maxDrawdown)?`${(r.maxDrawdown*100).toFixed(2)}%`:'—')}${detail('Account opened',stamp(r?.createdAt))}</div></section></div>`;}
function detail(k,v){return `<div><span>${k}</span><strong>${v}</strong></div>`;}
function predictionPanel(r){const f=r?.forecast;const percentage=v=>Number.isFinite(v)?(v*100).toFixed(1)+'%':'—';return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">PREDICTIONS → OUTCOMES</span><h2>What the model expects</h2><p>Experimental 1-hour projections · recorded before the outcome · not order instructions</p></div>${badge('SHADOW ONLY')}</div><div class="stats-row prediction-stats">${stat('Closed-trade win rate',percentage(f?.tradeWinRate),`${f?.profitableTrades??0} profitable / ${f?.closedTrades??0} closed trades`)}${stat('Forward direction accuracy',percentage(f?.directionalAccuracy),`${f?.scored??0} scored forecasts · excludes initial history`)}${stat('Predicted closed-trade P/L',signed(f?.predictedTradePnl),`${f?.matchedTrades??0} trades with a matching 1h exit`)}${stat('Actual matched P/L',signed(f?.realizedMatchedPnl),'Same trades and forecast horizon')}</div>${f?.latest?.length?table(['Instrument / plan','Upward score','Projected net P/L','Historical scenarios','Timing'],f.latest.map(p=>{const d=r.decisions.find(d=>d.asset===p.asset);return `<tr><td><b>${esc(p.asset)}</b><small>${esc(d?.action??'WAIT')} · ${esc(d?.reason??'No decision')}<br>${p.eligibleSize?'Hypothetical':'Below venue minimum'} ${money(p.cost)} position</small></td><td>${percentage(p.upwardScore)}<small>Uncalibrated direction score</small></td><td class="${tone(p.expectedPnl)}">${signed(p.expectedPnl)}<small>After estimated round-trip costs</small></td><td>${signed(p.lowPnl)} to ${signed(p.highPnl)}<small>${pct(p.lowReturn)} to ${pct(p.highReturn)} underlying return<br>5th–95th historical scenarios, not loss limits</small></td><td>${stamp(p.issuedAt)}<small>Target ${stamp(p.dueAt)} · ${esc(p.status)}${p.status==='pending'&&Date.now()>p.dueAt+120000?' · awaiting worker reconciliation':''}</small></td></tr>`})):empty('Awaiting the first forecast cycle','New predictions start with the updated worker. Past results are never assigned invented predictions.')}<div class="details">${detail('Scored shadow scenarios · expected net P/L',signed(f?.scenarioExpectedPnl))}${detail('Same shadow scenarios · observed net P/L',signed(f?.scenarioObservedPnl))}${detail('Pending / expired forecasts',`${f?.pending??0} / ${f?.expired??0}`)}${detail('Mean absolute return error',percentage(f?.meanAbsoluteReturnError))}</div><div class="panel-foot">Scenarios are hypothetical independent positions, not portfolio returns. No probability of profit is available. Outcomes require a fresh quote within 2 minutes of the 1-hour target; missed targets expire. Closed trades with different holding periods are excluded from the matched P/L comparison.</div></section>`;}
function algorithm(){
 const options=engine==='Options research';
 let content;
 if(options){const view=researchView(ibkr);chartSeries=view.series;content=view.html}
 else {const r=paper;chartSeries=[{name:'Crypto $100',color:'#65ebc5',points:(r?.history||[]).map(p=>({time:p.time,value:p.stale?null:p.equity}))}];content=notice()+`<div class="stats-row">${stat('Equity',money(r?.equity),'CAD · original $100 account')}${stat('Net P/L',signed(r?.pnl),'After simulated costs')}${stat('Fills',r?String(r.trades.length):'—','Hourly strategy')}${stat('Strategy','Trend v1','BTC + ETH')}</div><section class="panel"><div class="panel-head"><h2>Account performance</h2></div>${chartHTML(chartSeries,{label:'Original crypto paper account in CAD'})}</section><section class="panel"><div class="panel-head"><h2>Latest decisions</h2></div>${table(['Instrument','Action','Reason'],(r?.decisions||[]).slice(0,4).map(d=>`<tr><td>${esc(d.asset)}</td><td>${esc(d.action)}</td><td>${esc(d.reason)}</td></tr>`))}</section><details id="crypto-details" class="disclosure"><summary>Crypto forecasts & results</summary>${predictionPanel(r)}</details>`;}
 return header('NORTHSTAR LAB','Algorithm','Observe. Execute in simulation. Measure the result.')+ibkrPanel(ibkr)+tabs(['Options research','Crypto $100'],engine,'data-engine')+content;
}
function markets(){chartSeries=[];return header('DISCOVER YOUR NEXT MOVE','Markets','Stocks, options and futures. One workspace.')+ibkrPanel(ibkr)+explorerView(ibkr,market);}

function render(background=false){const logged=signedIn();document.querySelector('nav').hidden=!logged;document.querySelector('.statusbar').hidden=!logged;patchDOM(document.querySelector('.top-meta'),logged?'<span class="badge">PAPER ACCOUNT</span>'+signOutButton():'');if(!logged){document.title='Northstar · Sign in';patchDOM(main,authView());bindAuth(main,render,refresh,()=>{ibkr=null;paper=null;market=null;errors={}});return;}const focused=document.activeElement;const focusKey=focused?.id==='refresh'?'#refresh':null;const focusAttr=['data-range','data-market-range','data-category','data-region','data-asset','data-ibkr-asset','data-account','data-engine'].find(a=>focused?.hasAttribute(a));const focusValue=focusAttr?focused.getAttribute(focusAttr):null;document.title=`Northstar · ${{overview:'Portfolio',algorithm:'Algorithm',markets:'Markets'}[page]}`;document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const openDetails=[...main.querySelectorAll('details[id][open]')].map(d=>d.id);patchDOM(main,page==='overview'?portfolio():page==='algorithm'?algorithm():markets(),{background});document.querySelector('#refresh').onclick=()=>refresh(true);main.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{range=b.dataset.range;render()});main.querySelectorAll('[data-market-range]').forEach(b=>b.onclick=()=>{marketRange=b.dataset.marketRange;render()});main.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;if(['Options','Futures','ETFs'].includes(category))region='US';else if(category==='Stocks')region='Canada';render()});main.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{region=b.dataset.region;render()});main.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{assetId=b.dataset.asset;render()});main.querySelectorAll('[data-ibkr-asset]').forEach(b=>b.onclick=()=>{ibkrAsset=b.dataset.ibkrAsset;render()});main.querySelectorAll('[data-account]').forEach(b=>b.onclick=()=>{account=b.dataset.account;render()});main.querySelectorAll('[data-engine]').forEach(b=>b.onclick=()=>{engine=b.dataset.engine;render()});for(const id of openDetails){const d=document.getElementById(id);if(d)d.open=true;}bindAuth(main,render,refresh,()=>{ibkr=null;paper=null;market=null;errors={}});if(page==='markets')bindExplorer(main,ibkr,market,render,background);else if(!(background&&main.querySelector('[data-chart]:hover,[data-chart]:focus-within')))bindChart(main,chartSeries);if(focusKey)main.querySelector(focusKey)?.focus({preventScroll:true});if(focusAttr)[...main.querySelectorAll(`[${focusAttr}]`)].find(b=>b.getAttribute(focusAttr)===focusValue)?.focus({preventScroll:true});const count=market?.assets?.filter(a=>Date.now()-a.observedAt<=120000).length||0;document.querySelector('#connection-status').textContent=`${count}/2 fresh crypto quotes · ${busy?'Refreshing…':'60s refresh'}`;}
async function get(url){const r=await fetch(url,{cache:'no-store',signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Data feed unavailable');return data;}
async function refresh(manual=false){if(!signedIn()||busy)return;busy=true;if(manual)render(true);const results=await Promise.allSettled([get('/api/paper'),get('/api/market'),get('/api/ibkr')]);for(const [i,key] of ['paper','market'].entries()){const r=results[i];errors[key]=r.status==='rejected'?r.reason.message:null;if(key==='paper')paper=r.status==='fulfilled'?r.value:null;else market=r.status==='fulfilled'?r.value:null;}ibkr=results[2].status==='fulfilled'?results[2].value:{enabled:false,status:'connection-unavailable',error:'IBKR connection status could not be loaded.'};busy=false;if(ibkr?.status==='locked'){lostSession(render);return;}render(true);}
function route(){const next=location.hash.slice(1);page=['overview','algorithm','markets'].includes(next)?next:'overview';if(next!==page)history.replaceState(null,'',`#${page}`);render();}
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView()};
window.addEventListener('hashchange',()=>{route();window.scrollTo(0,0)});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});route();checkAuth(()=>{render();if(signedIn())refresh()});setInterval(()=>{if(!document.hidden)refresh()},60000);

document.addEventListener('pointerdown',()=>{lastInteraction=Date.now()});
document.addEventListener('keydown',()=>{lastInteraction=Date.now()});
async function readIBKR(){const r=await fetch('/api/ibkr',{cache:'no-store',signal:AbortSignal.timeout(12000)});const value=await r.json();if(!r.ok&&!value.status)throw new Error('Feed unavailable');return value;}
setInterval(async()=>{
 if(!signedIn()||ibkrBusy||busy||document.hidden||Date.now()-lastIBKRPoll<(ibkr?.transport==='hosted'?30000:2000))return;
 ibkrBusy=true;lastIBKRPoll=Date.now();try{ibkr=await readIBKR()}catch{ibkr={enabled:false,transport:'hosted',status:'connection-unavailable',assets:[],note:'Could not reach the private feed. No current quotes can be verified.'}}finally{ibkrBusy=false;if(ibkr?.status==='locked')lostSession(render);else render(true)}
},2000);
